package com.yongdrel.payment_proof_service.adapter.in.web;
import com.yongdrel.payment_proof_service.adapter.out.persistence.PaymentProofEntity; import com.yongdrel.payment_proof_service.application.service.PaymentProofService; import jakarta.validation.constraints.NotBlank; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.security.oauth2.jwt.Jwt; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import java.util.*;
@RestController @RequestMapping("/api/payment-proofs") public class PaymentProofController{
 private final PaymentProofService service; public PaymentProofController(PaymentProofService s){service=s;}
 @PostMapping(consumes=MediaType.MULTIPART_FORM_DATA_VALUE) public Response submit(@RequestPart UUID orderId,@RequestPart @NotBlank String idempotencyKey,@RequestPart MultipartFile file,Authentication a){return Response.of(service.submit(orderId,claim(a,"sub"),claim(a,"tenant_id"),idempotencyKey,file));}
 @GetMapping("/{id}/download") public ResponseEntity<byte[]> download(@PathVariable UUID id,Authentication a){return ResponseEntity.ok().contentType(MediaType.APPLICATION_OCTET_STREAM).body(service.read(id,claim(a,"sub"),claim(a,"tenant_id"),organizer(a)));}
 @PatchMapping("/{id}") public Response verify(@PathVariable UUID id,@RequestParam boolean accepted,Authentication a){if(!organizer(a))throw new org.springframework.web.server.ResponseStatusException(HttpStatus.FORBIDDEN,"Organizer role required");return Response.of(service.verify(id,claim(a,"tenant_id"),accepted));}
 private static UUID claim(Authentication a,String n){if(!(a.getPrincipal() instanceof Jwt j))throw new org.springframework.web.server.ResponseStatusException(HttpStatus.UNAUTHORIZED,"Trusted JWT required");try{return UUID.fromString(j.getClaimAsString(n));}catch(Exception e){throw new org.springframework.web.server.ResponseStatusException(HttpStatus.FORBIDDEN,"Required UUID claim missing");}}
 private static boolean organizer(Authentication a){return a.getAuthorities().stream().anyMatch(x->x.getAuthority().equals("ROLE_ORGANIZER"));}
 public record Response(UUID id,UUID orderId,UUID userId,UUID tenantId,String filename,String mimeType,String checksum,String status,java.time.Instant submittedAt){static Response of(PaymentProofEntity p){return new Response(p.getId(),p.getOrderId(),p.getUserId(),p.getTenantId(),p.getFilename(),p.getMimeType(),p.getChecksum(),p.getStatus().name(),p.getSubmittedAt());}}
}
